static inline const EventInfo *findEvent(int code)
{
    std::size_t lo = 0;
    std::size_t hi = sizeof(kEvents) / sizeof(kEvents[0]);
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (kEvents[mid].code < code)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < sizeof(kEvents) / sizeof(kEvents[0]) && kEvents[lo].code == code)
        return &kEvents[lo];
    return nullptr;
}

static inline const LocationInfo *findLocation(int code)
{
    std::size_t lo = 0;
    std::size_t hi = sizeof(kLocations) / sizeof(kLocations[0]);
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (kLocations[mid].code < code)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < sizeof(kLocations) / sizeof(kLocations[0]) && kLocations[lo].code == code)
        return &kLocations[lo];
    return nullptr;
}
